import{_ as r,o as t,c as a,a5 as o}from"./chunks/framework.CXroN2RO.js";const i="/study/images/graphics/parallel-command-recording.svg",f=JSON.parse('{"title":"D3D12のコマンドリストを複数スレッドで記録する","description":"","frontmatter":{"title":"D3D12のコマンドリストを複数スレッドで記録する","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"描画コマンドを複数のCPUスレッドで記録し、パスの依存順に提出する。アロケータとリストの所有、フェンスで再利用するフレームスロット、計測の見方を扱う。","aliases":["並列コマンド記録","command list","command allocator","D3D12","ExecuteCommandLists","フレームスロット","frame in flight"],"verification":"MicrosoftのD3D12 APIリファレンスと公式マルチスレッドサンプルに照合（2026-11-06）"}},"headers":[],"relativePath":"graphics/optimization/parallel-command-recording.md","filePath":"graphics/optimization/parallel-command-recording.md"}'),n={name:"graphics/optimization/parallel-command-recording.md"};function s(d,e,c,l,m,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="d3d12のコマンドリストを複数スレッドで記録する" tabindex="-1">D3D12のコマンドリストを複数スレッドで記録する <a class="header-anchor" href="#d3d12のコマンドリストを複数スレッドで記録する" aria-label="Permalink to &quot;D3D12のコマンドリストを複数スレッドで記録する&quot;">​</a></h1><p>Direct3D 12では、描画やコピーの命令をコマンドリストへ記録し、コマンドキューへ提出します。複数のCPUスレッドが別々のリストを記録すれば、一つのフレームを組み立てるCPU時間を短くできる場合があります。例えば、影を作るパスと、その影を参照するライティングパスは、使うリソースと状態を先に決めておけば、CPU上で同時に記録できます。GPUへの提出では、影を作ってから参照する順序を守ります。<a href="https://learn.microsoft.com/en-us/samples/microsoft/directx-graphics-samples/d3d12-multithreading-sample-win32/" target="_blank" rel="noreferrer">MicrosoftのD3D12マルチスレッドサンプル</a> · <a href="/study/graphics/api/directx12.html">DirectX 12の基礎</a></p><figure class="study-figure"><img src="'+i+'" alt="ワーカーAとBがそれぞれ専用のアロケータとリストで影とライティングのコマンドを同時に記録する。Bが先に記録を終えても、提出側はAのあとにBを並べる。GPUがそのフレームの命令を実行し、フェンス値に達するとアロケータなどを再利用できる。" width="760" height="464" loading="lazy"><figcaption>CPUでの記録、GPUへ渡す順序、フレームスロットの再利用を決める目印。<a href="/study/images/graphics/parallel-command-recording.svg" target="_blank" rel="noopener noreferrer">並列記録の図を拡大</a></figcaption></figure><h2 id="記録中のリストとアロケータを一人で持つ" tabindex="-1">記録中のリストとアロケータを一人で持つ <a class="header-anchor" href="#記録中のリストとアロケータを一人で持つ" aria-label="Permalink to &quot;記録中のリストとアロケータを一人で持つ&quot;">​</a></h2><p><strong>コマンドリスト</strong>は描画や状態設定を追加するためのオブジェクトです。<strong>コマンドアロケータ</strong>は、記録された命令を保持するメモリを管理します。記録中は、一つのリストとそのアロケータを一つのワーカーが担当します。同じアロケータを使って複数のリストを同時に記録することはできません。一つのワーカーがリストを閉じ、次のリストを同じアロケータで順に記録することはできます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/recording-command-lists-and-bundles" target="_blank" rel="noreferrer">Microsoftのコマンドリスト記録とアロケータの仕様</a></p><table tabindex="0"><thead><tr><th>操作</th><th>実行できる時点</th></tr></thead><tbody><tr><td>コマンドリストの <code>Close</code></td><td>そのリストへの命令の追加を終えた時点。成功したリストを提出側へ渡す。</td></tr><tr><td>コマンドリストの <code>Reset</code></td><td>リストが閉じており、次の記録に使える同じ種類のアロケータを渡せる時点。提出済みの前回の命令をGPUが実行中でも、次の記録を始められる。</td></tr><tr><td>コマンドアロケータの <code>Reset</code></td><td>対応するリストの記録がなく、このアロケータに記録した命令をGPUがすべて使い終えた時点。提出待ちの記録も先に提出するか、破棄する。</td></tr></tbody></table><p>リストをリセットして次の記録を始めても、GPUが前回使う記録のメモリはアロケータに残ります。前回と同じ記録を再提出する場合は、その記録の前回の実行完了も確認します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12graphicscommandlist-reset" target="_blank" rel="noreferrer">リストのReset</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandallocator-reset" target="_blank" rel="noreferrer">アロケータのReset</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-executecommandlists" target="_blank" rel="noreferrer">ExecuteCommandListsの契約</a></p><h2 id="パスの依存関係で提出順を決める" tabindex="-1">パスの依存関係で提出順を決める <a class="header-anchor" href="#パスの依存関係で提出順を決める" aria-label="Permalink to &quot;パスの依存関係で提出順を決める&quot;">​</a></h2><p>例えばワーカーAはシャドウマップへ深度を書くパスを、ワーカーBはライティングで同じマップを読むパスを記録します。作業を配る前に、AのリストをBのリストより先に提出することと、両者の間でマップの状態を <code>DEPTH_WRITE</code> から <code>PIXEL_SHADER_RESOURCE</code> へ遷移させることを決めます。各ワーカーには、担当するリソースと状態遷移を記したパスの計画を渡します。Bが先にリストを閉じても、提出側は両方を集めてA、Bの順で提出します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/using-resource-barriers-to-synchronize-resource-states-in-direct3d-12" target="_blank" rel="noreferrer">Microsoftのリソースバリアの仕様</a></p><p>同じキューでも、一回の <code>ExecuteCommandLists</code> に複数のリストを渡すと、ドライバーは先行リストの処理がすべて終わる前に、後続リストの実行可能な処理を始められます。必要な依存関係はバリアで表します。別キューへ結果を渡す場合は、生成側のキューの <code>Signal</code> と消費側のキューの <code>Wait</code> で順序を組み、キューの種類に応じたリソース状態も扱います。<a href="https://learn.microsoft.com/en-us/windows/win32/api/d3d12/nf-d3d12-id3d12commandqueue-executecommandlists" target="_blank" rel="noreferrer">ExecuteCommandListsでの一括提出</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">Microsoftの複数キュー間の同期</a></p><h2 id="フレームスロットをフェンスで回す" tabindex="-1">フレームスロットをフェンスで回す <a class="header-anchor" href="#フレームスロットをフェンスで回す" aria-label="Permalink to &quot;フレームスロットをフェンスで回す&quot;">​</a></h2><p>CPUが次のフレームを記録する間、GPUが前のフレームを実行していることがあります。同時に進めるフレームを二つまでとするなら、再利用する一時領域を二組の<strong>フレームスロット</strong>に分ける設計ができます。二つのワーカーが同時に記録するなら、各スロットにワーカー別のアロケータを一つずつ置き、合計四つで回す構成が一例です。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/recording-command-lists-and-bundles#recording-command-lists" target="_blank" rel="noreferrer">Microsoftのアロケータプールの説明</a></p><ol><li>空いているスロットで、各ワーカーが自分のアロケータを使って記録します。</li><li>提出側がリストをキューへ渡し、同じキューで最後の使用のあとにフェンス値を通知する命令を入れます。スロットにその値を記録します。</li><li>そのスロットへ戻ったら、CPUがフェンスの到達を確認してアロケータをリセットします。コマンドが参照するシェーダー可視の記述子スロットや定数用の一時領域も、最後のGPU参照が終わってから使い回します。複数キューで使う領域なら、すべての使用を追います。</li></ol><p>記述子や参照先をどの時点から保持するかは、ルートシグネチャの静的・揮発性の指定にも従います。例えばフレーム用のシェーダー可視記述子は、ワーカー別の範囲に分け、記録前に用意してGPU完了まで維持できます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/root-signature-version-1-1" target="_blank" rel="noreferrer">Root Signature 1.1の契約</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースと一時領域の寿命</a></p><h2 id="cpuの記録時間と待ち時間を計測する" tabindex="-1">CPUの記録時間と待ち時間を計測する <a class="header-anchor" href="#cpuの記録時間と待ち時間を計測する" aria-label="Permalink to &quot;CPUの記録時間と待ち時間を計測する&quot;">​</a></h2><p>同じシーンで、フレームの記録開始から提出までの経過時間、ワーカー別の記録時間、提出側が最後のワーカーを待つ時間、リスト数と提出回数を比べます。例えば一つの大きなパスに仕事が集中する場合は、同じパス内で描画の範囲を分けられるかを調べます。リストを細かく分けるほど、初期状態の設定、ジョブの配布、記録結果の回収も増えます。GPU時間とキューに仕事が来ていない区間も併せて見ると、CPU側の変更がフレーム全体にどう効いたかを確かめられます。<a href="https://devblogs.microsoft.com/pix/timing-captures-new/" target="_blank" rel="noreferrer">Microsoft PIXのTiming Captures</a> · <a href="/study/graphics/optimization/gpu-timestamp-queries.html">GPUタイムスタンプクエリ</a></p><p>アセットを準備するワーカーは、例えばメッシュを読み、頂点とインデックスをCPU側に用意し、描画側へ渡します。記録ワーカーは、その描画で参照できるリソースを使ってコマンドリストを組み立てます。二つの段階をつなぐときは、データを受け取る時点と、アップロードが済んで描画で使える時点をそれぞれ追います。<a href="/study/game/asset-worker-handoff.html">アセットワーカーから描画側へ渡す設計</a></p>',17)])])}const u=r(n,[["render",s]]);export{f as __pageData,u as default};
